import { createReadStream } from "node:fs";
import { mkdir, readdir, rm, stat, writeFile } from "node:fs/promises";
import { dirname, join, resolve, sep } from "node:path";
import type { Readable } from "node:stream";

/**
 * Where file bytes live. Keys are opaque, generated by the server (never from user input). A
 * hosted provider (object storage behind a CDN) implements this later; the choice is pending.
 */
export interface ObjectStorage {
  put(key: string, data: Buffer): Promise<void>;
  read(key: string): Readable;
  size(key: string): Promise<number | null>;
  delete(key: string): Promise<void>;
  /** Keys under a prefix with their last change, for cleanup. */
  list(prefix: string): Promise<{ key: string; modifiedAt: Date }[]>;
}

export const OBJECT_STORAGE = Symbol("OBJECT_STORAGE");

const SAFE_KEY = /^[a-z0-9][a-z0-9/_-]{0,200}$/;

/** Development and tests only: files on the local disk. Production refuses this driver. */
export class LocalDiskStorage implements ObjectStorage {
  private readonly root: string;
  constructor(dir: string) {
    this.root = resolve(dir);
  }

  /** Keys are checked so nothing can escape the storage folder. */
  private path(key: string): string {
    if (!SAFE_KEY.test(key) || key.includes("..")) throw new Error("invalid storage key");
    const p = resolve(join(this.root, key));
    if (!p.startsWith(this.root + sep)) throw new Error("invalid storage key");
    return p;
  }

  async put(key: string, data: Buffer): Promise<void> {
    const p = this.path(key);
    await mkdir(dirname(p), { recursive: true });
    await writeFile(p, data);
  }

  read(key: string): Readable {
    return createReadStream(this.path(key));
  }

  async size(key: string): Promise<number | null> {
    try {
      return (await stat(this.path(key))).size;
    } catch {
      return null;
    }
  }

  async delete(key: string): Promise<void> {
    await rm(this.path(key), { force: true, recursive: true });
  }

  async list(prefix: string): Promise<{ key: string; modifiedAt: Date }[]> {
    const base = this.path(prefix);
    const out: { key: string; modifiedAt: Date }[] = [];
    const walk = async (dir: string): Promise<void> => {
      let entries;
      try {
        entries = await readdir(dir, { withFileTypes: true });
      } catch {
        return;
      }
      for (const e of entries) {
        const full = join(dir, e.name);
        if (e.isDirectory()) await walk(full);
        else {
          out.push({
            key: full
              .slice(this.root.length + 1)
              .split(sep)
              .join("/"),
            modifiedAt: (await stat(full)).mtime,
          });
        }
      }
    };
    await walk(base);
    return out;
  }
}
